package com.novacommerce.order.application; import com.novacommerce.order.api.error.OrderException; import com.novacommerce.order.domain.order.CustomerOrder; import com.novacommerce.order.infrastructure.persistence.OrderRepository; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service public class OrderQueryService{private final OrderRepository orders;public OrderQueryService(OrderRepository o){orders=o;}@Transactional(readOnly=true)public Page<CustomerOrder>list(UUID owner,int page,int size){return orders.findByOwnerIdOrderByCreatedAtDesc(owner,PageRequest.of(page,Math.min(size,50)));}@Transactional(readOnly=true)public CustomerOrder get(UUID owner,UUID id){return orders.findByIdAndOwnerId(id,owner).orElseThrow(()->new OrderException(HttpStatus.NOT_FOUND,"ORDER_NOT_FOUND","Order not found"));}}
